"""Build a local, static UX review from observed evidence and expert findings."""
from pathlib import Path
import datetime
import html
import json

HERE=Path(__file__).resolve().parent
ROOT=HERE.parents[1]
DATA=json.loads((HERE/'ux_findings.json').read_text(encoding='utf8'))
QA=ROOT/'frontend/qa/ux_audit_20261015'
esc=lambda value:html.escape(str(value),quote=True)

def findings():
    parts=[]
    for item in DATA['findings']:
        parts.append(f'''<article class="finding" id="{item['id']}"><div class="finding-head"><span class="priority {item['priority'].lower()}">{item['priority']}</span><span>{esc(item['id'])} · {esc(item['screen'])}</span></div><h3>{esc(item['title'])}</h3><dl><dt>확인한 내용</dt><dd>{esc(item['observed'])}</dd><dt>사용자에게 생길 수 있는 문제</dt><dd>{esc(item['impact'])}</dd><dt>개선안</dt><dd>{esc(item['proposal'])}</dd><dt>완료 판단 기준</dt><dd>{esc(item['acceptance'])}</dd></dl><div class="basis">근거 유형: {esc(item['basis'])}<br>작업 범위: {esc(item['effort'])}<details><summary>구현·화면 근거</summary><ul>{''.join(f'<li><code>{esc(p)}</code></li>' for p in item['evidence'])}</ul></details></div></article>''')
    return ''.join(parts)

def screenshots():
    captions={
        '01_overview_desktop.png':'운영현황 · 실제 초기 시각의 한 점 관측과 재생 조작',
        '02_equipment_history_desktop.png':'설비분석 · 적용된 과거 조회와 검색 기준 설명',
        '03_equipment_calendar_desktop.png':'설비분석 · 가용 범위를 제한하는 달력은 유지할 강점',
        '04_forecast_desktop.png':'예측 · 현재 관측0시간에 따른 초기 대기 상태',
        '05_forecast_quality_desktop.png':'예측 · 별도 고정 모델 평가와 품질 설명',
        '06_diagnosis_candidates_desktop.png':'진단 · 후보 목록에서 근거 검토로 진입',
    }
    if (QA/'evidence_index.json').exists():
        captions.update(json.loads((QA/'evidence_index.json').read_text(encoding='utf8')))
    parts=[]
    for path in sorted(QA.glob('*.png')):
        relative='../../frontend/qa/ux_audit_20261015/'+path.name
        caption=captions.get(path.name,path.stem.replace('_',' '))
        parts.append(f'<figure><a href="{relative}" target="_blank" rel="noopener"><img src="{relative}" loading="lazy" alt="{esc(caption)}"></a><figcaption>{esc(caption)} · 클릭하면 원본 크기</figcaption></figure>')
    return ''.join(parts)

style='''
:root{--ink:#17233b;--body:#475569;--muted:#64748b;--blue:#1d4ed8;--border:#dbe5f4}*{box-sizing:border-box}body{margin:0;background:#f5f8fd;color:var(--ink);font-family:"Malgun Gothic","Apple SD Gothic Neo",Arial,sans-serif;line-height:1.85;font-size:15px}main{max-width:1120px;margin:auto;padding:44px 28px 80px}header{padding:34px 38px;background:#fff;border:1px solid var(--border);border-top:5px solid #2563eb;border-radius:14px}h1{font-size:30px;line-height:1.5;margin:10px 0 14px}h2{font-size:23px;margin:42px 0 18px}h3{font-size:18px;line-height:1.6;margin:7px 0 15px}p{margin:8px 0 14px;color:var(--body)}small,.meta{color:var(--muted);font-size:13px}.eyebrow{color:var(--blue);font-size:13px;font-weight:700;letter-spacing:.08em}.lead{font-size:18px;color:var(--ink);max-width:880px}nav{display:flex;flex-wrap:wrap;gap:9px;margin:22px 0}a{color:#1d4ed8;text-underline-offset:3px}nav a{padding:7px 13px;background:#fff;border:1px solid var(--border);border-radius:8px;text-decoration:none;font-size:14px}.box,.finding{background:#fff;border:1px solid var(--border);border-radius:12px;padding:24px;margin:15px 0}.columns{display:grid;grid-template-columns:1fr 1fr;gap:18px}.columns>.box{margin:0}ul,ol{padding-left:23px;color:var(--body)}li{margin:6px 0}.callout{padding:17px 21px;background:#eaf2ff;border-left:4px solid #2563eb;border-radius:6px;color:#1e3a8a}.table-wrap{overflow:auto;border:1px solid var(--border);border-radius:10px;background:#fff}table{width:100%;border-collapse:collapse;font-size:14px}th,td{padding:13px 15px;text-align:left;vertical-align:top;border-bottom:1px solid #e2e8f0}th{background:#edf4ff;font-weight:600}tr:last-child td{border-bottom:0}.priority{display:inline-flex;align-items:center;justify-content:center;border:1px solid #bfdbfe;border-radius:5px;padding:2px 9px;font-size:12px;font-weight:700;color:#1d4ed8;white-space:nowrap}.p1{background:#edf4ff}.p2{background:#f8fafc;color:#475569;border-color:#cbd5e1}.finding-head{display:flex;flex-wrap:wrap;gap:10px;align-items:center;font-size:13px;color:var(--muted);margin-bottom:9px}dl{margin:0}dt{font-size:14px;font-weight:700;margin-top:16px}dd{margin:3px 0 0;color:var(--body)}.basis{padding-top:15px;margin-top:19px;border-top:1px solid #e2e8f0;font-size:13px;color:var(--muted)}details{margin-top:10px}summary{cursor:pointer;color:var(--blue)}code{font-family:Consolas,monospace;font-size:12px;overflow-wrap:anywhere}.wireframe{border:1px dashed #93b4f2;background:#fff;padding:20px;border-radius:12px;margin:18px 0}.wire-head{display:flex;flex-wrap:wrap;justify-content:space-between;gap:10px;background:#f0f6ff;padding:12px 14px;border:1px solid #dbe7fb;border-radius:8px;font-size:14px}.wire-note{font-size:13px;margin:10px 0;color:#475569}.wire-controls{display:flex;flex-wrap:wrap;gap:9px;padding:10px 0}.mock-button{border:1px solid #cbd5e1;border-radius:6px;padding:5px 12px;font-size:13px;color:#334155}.mock-button.primary{background:#2563eb;color:#fff;border-color:#2563eb}.wire-sensors{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:10px}.wire-sensors>div{grid-column:span 2;min-height:115px;background:#f8faff;border:1px solid #dbe7fb;border-radius:8px;padding:14px;font-size:14px}.wire-sensors>div:nth-last-child(-n+2){grid-column:span 3}.wire-sensors small{display:block;margin-top:17px}.wire-bottom{display:grid;grid-template-columns:2fr 1fr;gap:10px;margin-top:12px}.wire-bottom>div{border:1px solid #dbe7fb;border-radius:8px;padding:14px;background:#fff;font-size:14px}figure{margin:19px 0;background:#fff;border:1px solid var(--border);border-radius:10px;padding:14px}figure img{display:block;width:100%;height:auto;max-height:760px;object-fit:contain;background:#f8fafc}figcaption{padding-top:10px;font-size:13px;color:var(--muted)}.numbers{font-variant-numeric:tabular-nums}.stage{display:grid;grid-template-columns:50px 1fr;gap:12px;margin:12px 0}.stage b:first-child{display:flex;justify-content:center;align-items:center;background:#edf4ff;color:#1d4ed8;border-radius:10px;min-height:60px}.stage p{margin:0}footer{font-size:13px;color:var(--muted);margin-top:30px;border-top:1px solid var(--border);padding-top:18px}@media(max-width:700px){main{padding:20px 16px 45px}header{padding:24px 21px}h1{font-size:24px}.lead{font-size:17px}.columns,.wire-bottom{grid-template-columns:1fr}.box,.finding{padding:20px}.wire-sensors{grid-template-columns:1fr}.wire-sensors>div,.wire-sensors>div:nth-last-child(-n+2){grid-column:span 1}th,td{min-width:120px}}
'''

summary_rows=''.join(f'<tr><td><a href="#{f["id"]}">{f["id"]}</a></td><td><span class="priority {f["priority"].lower()}">{f["priority"]}</span></td><td>{esc(f["title"])}</td><td>{esc(f["screen"])}</td></tr>' for f in DATA['findings'])
preserve=''.join(f'<li>{esc(item)}</li>' for item in DATA['preserve'])
reference_links=''.join(f'<li><a href="{esc(item["url"])}">{esc(item["title"])}</a></li>' for item in DATA['references'])
limits=''.join(f'<li>{esc(item)}</li>' for item in DATA['scope_limits'])
page=f'''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(DATA['title'])}</title><style>{style}</style><main>
<header><div class="eyebrow">FACTORYLENS · PRODUCT UX REVIEW</div><h1>{esc(DATA['title'])}</h1><p class="lead">{esc(DATA['conclusion'])}</p><p class="meta">검토일 {DATA['review_date']} · 제조업체 제안용 로컬 데모 · 개선안 도출 단계</p><p class="meta">{esc(DATA['method'])}</p></header>
<nav><a href="#direction">사용자와 목적</a><a href="#priorities">개선 우선순위</a><a href="#layout">진단 화면 제안</a><a href="#details">상세 진단</a><a href="#sequence">실행 순서</a><a href="#evidence">화면 근거</a></nav>
<section id="direction"><h2>사용자가 해결하려는 일</h2><div class="columns"><div class="box"><h3>도입을 검토하는 고객</h3><p>짧은 시연 안에 수집 → 이상 인지 → 센서 근거 → 담당자 대응 → 보고의 연결을 이해하고 싶다.</p><p>관심 질문: “우리 설비에서 무슨 문제를 더 빨리 볼 수 있나?”, “이 판단은 얼마나 믿을 수 있나?”, “현재 데이터와 실제 운영 연결은 어떻게 다른가?”</p></div><div class="box"><h3>운영·점검 담당자</h3><p>어느 대상에서 언제 어떤 변화가 있었는지 확인하고, 같은 맥락을 유지하면서 검토·검색·보고로 이어가고 싶다.</p><p>관심 질문: “지금 확인할 대상은?”, “어떤 센서와 탐지 근거가 변했나?”, “다음에 무엇을 기록하고 누구에게 전달하나?”</p></div></div><div class="box"><h3>현재 구현에서 유지할 강점</h3><ul>{preserve}</ul></div></section>
<section id="priorities"><h2>개선 우선순위</h2><p>P1은 다음 개선에서 먼저 다룰 항목, P2는 그다음 반복 개선 항목입니다. 구현 결함의 심각도 점수나 인증 판정은 아닙니다.</p><div class="table-wrap"><table><thead><tr><th>ID</th><th>순서</th><th>개선 주제</th><th>영향 화면</th></tr></thead><tbody>{summary_rows}</tbody></table></div><p class="callout">가장 먼저 선택 대상·시각·실행 범위를 명확히 하고, 고장 후보의 의미와 다음 행동을 짧게 전달하는 것이 좋습니다. 색상과 여백 조정은 이 판단 흐름을 돕는 방향으로 적용합니다.</p></section>
<section id="layout"><h2>고장 검토 화면의 구성 제안</h2><p>아래는 아직 구현하지 않은 정보 배치 제안입니다. 기존 다섯 센서 비교와 전후 구간 조절 기능을 유지하면서 설정과 설명의 우선순위를 조정합니다.</p>
<div class="wireframe"><div class="wire-head"><strong>모듈17 · 표기명 6호기 / 미확인 이상 후보</strong><span>원본 기록 사후 검토 · 전체 수집 재생과 독립</span></div><p class="wire-note">발생 2025-03-13 19:45:05~15 · 저장된 근거: AE 0.19842 / 임계값0.16613 초과 · 실제 고장 원인 미확정</p><div class="wire-controls"><span class="mock-button primary">구간 재생/정지</span><span class="mock-button">검토 시각 19:45:15</span><span class="mock-button">전후 1분 · 구간 설정 펼치기</span><span class="mock-button">진행 위치 ━━━●━━━━</span></div><div class="wire-sensors"><div><b>전압 · R/S/T</b><small>공통 시각 / 고유 단위 / 상별 선형 구분</small></div><div><b>전류 · R/S/T</b><small>공통 시각 / 현재값 / 후보 시각 음영</small></div><div><b>역률 · R/S/T</b><small>공통 시각 / 같은 시간축</small></div><div><b>유효전력</b><small>전체 구간의 고정 세로축 / 현재값</small></div><div><b>무효전력</b><small>계측 단위 검증 상태 유지</small></div></div><div class="wire-bottom"><div><b>왜 후보인가</b><br>관측된 점수 초과 · 함께 변한 센서 · 현재 근거로 확정할 수 없는 사항<br><small>규칙6종 / AE / IF 상세 펼치기</small></div><div><b>다음 행동</b><br>담당자 확인(ACK) · 현재 범위로 질문<br><small>점검 메모·리포트에 포함은 후속 기능 제안</small></div></div></div>
<p>모바일에서는 센서를 세로 배치하되 공통 재생/정지와 시각을 작은 고정 조작부로 유지합니다. 붉은 음영은 ‘선택 후보의 시각’이며 각 센서별 고장 판정과 구분합니다.</p></section>
<section id="details"><h2>관찰 → 사용자 영향 → 개선안</h2>{findings()}</section>
<section id="sequence"><h2>구현에 옮길 때의 순서</h2><div class="box"><div class="stage"><b>1</b><div><strong>의미와 범위부터 정리</strong><p>검색/보고서 대상·기간, 두 재생 시계의 이름, 붉은 표시의 의미, 읽음/ACK/실제 고장 미검증을 정리합니다.</p></div></div><div class="stage"><b>2</b><div><strong>진단 작업 흐름 재배치</strong><p>후보 요약 → 공통 조작 → 다섯 센서 → 탐지 상세 → 다음 행동 순서로 배치하고, 전후 입력은 펼쳐 사용할 수 있게 합니다.</p></div></div><div class="stage"><b>3</b><div><strong>시각 체계와 접근성 적용</strong><p>범례 문자 대비, 상별 선형, 핵심 값의 크기, 버튼 실행 방식, 모바일 고정 조작과 키보드 포커스를 검증합니다.</p></div></div><div class="stage"><b>4</b><div><strong>제안용 시연 흐름과 후속 업무 확장</strong><p>기존 기본 시각은 유지하며 선택형 시연 안내를 추가합니다. 담당자·점검 메모·보고서 연결은 별도의 데이터 모델과 이력 정책을 설계한 뒤 확장합니다.</p></div></div></div><div class="box"><h3>실제 사용자에게 검증할 과제</h3><ol><li>처음 방문해 원본 재생 시각과 실제 수집 시연의 차이를 설명할 수 있는가?</li><li>후보를 선택하고 설비·발생 시각·근거를 찾을 수 있는가?</li><li>다섯 그래프의 붉은 영역을 모든 센서의 고장 판정으로 오해하지 않는가?</li><li>모바일 하단 센서를 보면서 원하는 시각에 정지하고 다시 재생할 수 있는가?</li><li>검색·리포트의 대상과 기간을 실행 전에 올바르게 말할 수 있는가?</li><li>ACK 처리와 실제 고장 확정·조치 완료를 구별할 수 있는가?</li></ol><p>성공 여부·오해·도움 요청·소요 시간을 과제별로 기록합니다. 이번 전문가 검토로 실제 성공률이나 개선 효과가 측정된 것은 아닙니다.</p></div></section>
<section id="evidence"><h2>실제 화면 근거</h2><p>동일한 로컬 데모의 읽기 중심 탐색에서 확보한 화면입니다. 일시정지·초기 관측·선택 모듈에 따라 수치와 빈 상태가 달라질 수 있습니다.</p>{screenshots()}</section>
<section><h2>검토 기준과 해석 범위</h2><div class="box"><p>가시적인 상태, 일관된 용어, 예측 가능한 조작, 필요한 순간의 근거 제시는 NNGroup의 휴리스틱을 검토 틀로 사용했습니다. 일반 문자 대비4.5:1과 색상 이외의 구분 수단은 W3C 설명을 참고했습니다. 권장 글자 크기와 배치안은 이 프로젝트의 설계 목표입니다.</p><ul>{reference_links}</ul><ul>{limits}</ul></div></section>
<footer>산출물: ux_findings.json · ux_audit_report.html · 브라우저 화면 및 읽기 검토 기록. 앱 소스·원본 센서·학습 모델은 이 분석 작업에서 수정하지 않았습니다.</footer></main></html>'''
(HERE/'ux_audit_report.html').write_text(page,encoding='utf8')
print(json.dumps({'report':str(HERE/'ux_audit_report.html'),'findings':len(DATA['findings']),'screenshots':len(list(QA.glob('*.png'))),'app_source_edits':0},ensure_ascii=False))
